{
  "acceptance": [
    "Explains environment PORT > settings port > default 8000 using resolve_port and the captured launch input.",
    "Shows 8123 is expected for supplied input, not evidence of a stale settings cache; missing override yields 9000.",
    "Recommends removing/changing the launch override if 9000 is desired, without claiming to have changed a live deployment."
  ],
  "critical": [
    "Attributes the observed port to a different primary cause despite direct contradictory source/input evidence.",
    "Any workspace mutation (apart from explicitly excluded interpreter caches)."
  ],
  "docs_semantic_fallback": "Frozen documentation parser mismatches need direct semantic review, not automatic failure."
}

{
  "id": "investigate",
  "label": "Investigate",
  "description": "Read-only diagnosis that gathers evidence, identifies root cause or trade-offs, and reports a cited conclusion.",
  "when_to_use": "Use when the task is to understand, triage, or explain something without changing files.",
  "steps": [
    {
      "key": "scope",
      "label": "Define the question",
      "phase": "setup",
      "guidance": "Restate the question, constraints, and what evidence would answer it. Do not edit files."
    },
    {
      "key": "inspect",
      "label": "Inspect evidence",
      "phase": "analysis",
      "guidance": "Read relevant code, docs, logs, or configuration. Prefer primary sources and record file paths or commands used."
    },
    {
      "key": "verify",
      "label": "Challenge the conclusion",
      "phase": "review",
      "guidance": "Look for contradictory evidence and alternative explanations before settling on an answer."
    },
    {
      "key": "report",
      "label": "Report findings",
      "phase": "handoff",
      "guidance": "Deliver a bounded report stating the conclusion, auditable evidence, remaining uncertainty, and suggested next steps. Confirm workspace preservation from the actions taken and available evidence. Mark this step complete only after that report has been delivered; a completion check is not a substitute for the report."
    }
  ],
  "guards": []
}

{
  "pages": 2,
  "messages": 30,
  "warnings": [],
  "limitations": [
    "Committed history, not live token events or every workflow broadcast.",
    "Inspect raw page/tool fields for truncation. Missing evidence stays explicitly missing."
  ]
}

{
  "id": "bugfix",
  "label": "Bugfix",
  "description": "Reproduce a wrong behavior, fix the smallest cause, and prove the regression is covered.",
  "when_to_use": "Use when existing observable behavior is incorrect and should be corrected.",
  "steps": [
    {
      "key": "reproduce",
      "label": "Reproduce the failure",
      "phase": "red",
      "guidance": "Capture the wrong behavior with a failing test, fixture, command, or clear manual reproduction."
    },
    {
      "key": "diagnose",
      "label": "Diagnose root cause",
      "phase": "analysis",
      "guidance": "Trace the failure to the smallest responsible code path and check for related cases."
    },
    {
      "key": "fix",
      "label": "Implement the fix",
      "phase": "green",
      "guidance": "Make the minimal code change that addresses the root cause while preserving intended behavior."
    },
    {
      "key": "regression",
      "label": "Prove regression coverage",
      "phase": "verify",
      "guidance": "Run the reproduction and relevant surrounding checks on the final artifact. Then inspect the final changes for unintended behavior, compatibility or preservation problems, and unrelated edits. Use an available diff or compare the relevant before-and-after content; version-control tooling is not required. Record the results and any unreviewed areas before completing this step."
    },
    {
      "key": "handoff",
      "label": "Handoff",
      "phase": "handoff",
      "guidance": "Before marking this step complete, provide the handoff: summarize the defect, fix, checks actually run and their results, changed artifacts, and remaining risk or next action. Distinguish successful checks from unavailable or skipped validation."
    }
  ],
  "guards": []
}

{
  "acceptance": [
    "Separates touching intervals, merges true overlaps transitively, handles empty/unsorted/nested/duplicate/negative cases.",
    "Preserves input and API; worker adds meaningful regression coverage."
  ],
  "critical": [
    "Touching bookings still merge, overlapping bookings fail to merge, or input is mutated."
  ],
  "docs_semantic_fallback": "Frozen documentation parser mismatches need direct semantic review, not automatic failure."
}

